def transform(grid):
    g = np.array(grid).copy()
    n = g.shape[0]
    colours = set(range(1, n + 1))

    def cands(a, y, x):
        return colours - set(a[y, :].tolist()) - set(a[:, x].tolist())

    # Constraint propagation: fill every hole that has exactly one possible colour.
    while True:
        forced = []
        for y in range(n):
            for x in range(n):
                if g[y, x] == 0:
                    c = cands(g, y, x)
                    if len(c) == 1:
                        forced.append((y, x, next(iter(c))))
        if not forced:
            break
        for y, x, v in forced:
            if g[y, x] == 0 and v in cands(g, y, x):
                g[y, x] = v
        emit(g, "Filled the holes whose row and column leave only one missing colour.")

    # Fallback backtracking if propagation alone did not finish the square.
    def solve(a):
        for y in range(n):
            for x in range(n):
                if a[y, x] == 0:
                    for v in sorted(cands(a, y, x)):
                        a[y, x] = v
                        if solve(a):
                            return True
                    a[y, x] = 0
                    return False
        return True

    if (g == 0).any():
        solve(g)
        emit(g, "Completed the remaining holes by search so every row and column has each colour once.")

    emit(g, "Final Latin square: each colour appears once per row and column.")
    return g
